package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.New(0, 0)
var WsNet decimal.Decimal = decimal.New(0, 0)
var WsTotalTax decimal.Decimal = decimal.New(0, 0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxRec TaxRec
var inputDone bool

var taxFileScanner *bufio.Scanner
var taxFile *os.File

func formatEdited(val decimal.Decimal, pic string) string {
	parts := strings.Split(pic, ".")
	leftPic := parts[0]
	rightPic := ""
	if len(parts) > 1 {
		rightPic = parts[1]
	}
	// count digit placeholders in left
	intDigits := 0
	for _, c := range leftPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for _, c := range rightPic {
		if c == 'Z' || c == '9' {
			decDigits++
		}
	}

	// truncate high-order digits: mod 10^intDigits
	// Work with absolute value (no sign in these pics)
	if val.IsNegative() {
		val = val.Neg()
	}
	// Ensure val is scaled correctly (should already be 2 dec)
	// Get integer part and fractional part
	// Use val.Truncate to decDigits? For display, just take quantized value
	// val already truncated/rounded to 2 dec so fine

	// Separate integer and fraction
	// Multiply to get integer of all digits
	// Easier: integer part = floor(val)
	intPart := val.Truncate(0)
	// for decDigits>0, fractional:
	var fracVal int64
	if decDigits > 0 {
		fracDec := val.Sub(intPart).Abs()
		// shift decDigits
		fracDec = fracDec.Shift(int32(decDigits))
		// truncate (should be integer)
		fracDec = fracDec.Truncate(0)
		fracVal = fracDec.IntPart()
		if fracVal < 0 {
			fracVal = -fracVal
		}
	}

	// modulo for overflow: intPart mod 10^intDigits
	mod := decimal.New(1, int32(intDigits)) // 10^intDigits
	// keep low-order digits
	intPartMod := intPart.Mod(mod)
	// intPartMod may be negative, fix
	if intPartMod.IsNegative() {
		intPartMod = intPartMod.Add(mod)
	}
	intVal := intPartMod.IntPart() // fits into int64 for our sizes (max 8 digits)

	// Build integer digit string zero padded
	intStr := fmt.Sprintf("%0*d", intDigits, intVal)

	// Build left result
	leftResult := []rune(leftPic)
	// Map digits to placeholder positions
	digitIdx := 0
	for i, ch := range leftPic {
		if ch == 'Z' || ch == '9' {
			leftResult[i] = rune(intStr[digitIdx])
			digitIdx++
		} else {
			// comma stays for now
			leftResult[i] = ch
		}
	}
	// Z suppression
	suppressed := true
	for i, pch := range leftPic {
		if pch == ',' {
			if suppressed {
				leftResult[i] = ' '
			} else {
				leftResult[i] = ','
			}
			continue
		}
		// pch is Z or 9
		dc := leftResult[i]
		if suppressed {
			if pch == 'Z' && dc == '0' {
				leftResult[i] = ' '
				// remain suppressed
			} else {
				// stop suppression, keep digit as is (could be 0 for 9)
				suppressed = false
			}
		} else {
			// already not suppressed, keep digit
		}
	}

	result := string(leftResult)
	if decDigits > 0 {
		fracStr := fmt.Sprintf("%0*d", decDigits, fracVal)
		result = result + "." + fracStr
	}
	return result
}

func formatCount(count int64, digits int) string {
	// unedited numeric: zero-padded to digit count
	// Handle overflow: keep low-order digits?
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	v := count % mod
	return fmt.Sprintf("%0*d", digits, v)
}

func storePIC9V99(val decimal.Decimal, intDigits int) decimal.Decimal {
	// Truncate to 2 decimal scale toward zero
	q := val.Truncate(2)
	// Overflow: keep low-order digits that fit
	// Total digits = intDigits + 2 fractional digits as integer = val*100
	// So modulo 10^(intDigits+2)
	modExp := int32(intDigits + 2)
	mod := decimal.New(1, modExp)
	scaled := q.Shift(2) // q *100
	// Truncate scaled to integer (should be integer)
	scaled = scaled.Truncate(0)
	// modulo keeping sign? For positive only, but handle negative
	isNeg := scaled.IsNegative()
	if isNeg {
		scaled = scaled.Neg()
	}
	scaledMod := scaled.Mod(mod)
	if isNeg {
		scaledMod = scaledMod.Neg()
	}
	result := scaledMod.Shift(-2)
	// ensure scale 2
	result = result.Truncate(2)
	return result
}

func parsePIC9V99(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, 0)
	}
	// s contains digits only
	// Remove possible sign? not expected
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	} else if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	// keep only digits
	digits := ""
	for _, c := range s {
		if c >= '0' && c <= '9' {
			digits += string(c)
		}
	}
	if digits == "" {
		return decimal.New(0, 0)
	}
	d := decimal.RequireFromString(digits)
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func mainPara() {
	openInput()
	performReadPara()
	for !inputDone {
		performProcessPara()
	}
	closeTaxFile()
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", formatCount(WsCount, 3), WsTotalEd)
}

func readPara() {
	performReadPara()
}

func performReadPara() {
	if taxFileScanner == nil {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	if taxFileScanner.Scan() {
		line := taxFileScanner.Text()
		// COBOL LINE SEQUENTIAL: record padded with spaces
		// Pad or cut to 13
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		trId := line[0:5]
		trIncomeStr := line[5:13]
		taxRec.TrId = trId
		taxRec.TrIncome = parsePIC9V99(trIncomeStr, 2)
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func processPara() {
	performProcessPara()
}

func performProcessPara() {
	tenThousand := decimal.NewFromInt(10000)
	fortyThousand := decimal.NewFromInt(40000)
	rate10 := decimal.RequireFromString("0.10")
	rate20 := decimal.RequireFromString("0.20")
	rate30 := decimal.RequireFromString("0.30")
	thousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)

	var computed decimal.Decimal
	if taxRec.TrIncome.Cmp(tenThousand) <= 0 {
		computed = taxRec.TrIncome.Mul(rate10)
		computed = computed.Round(2) // ROUNDED
	} else {
		if taxRec.TrIncome.Cmp(fortyThousand) <= 0 {
			diff := taxRec.TrIncome.Sub(tenThousand)
			computed = thousand.Add(diff.Mul(rate20))
			computed = computed.Round(2)
		} else {
			diff := taxRec.TrIncome.Sub(fortyThousand)
			computed = sevenThousand.Add(diff.Mul(rate30))
			computed = computed.Round(2)
		}
	}
	WsTax = storePIC9V99(computed, 7)

	wsNetRaw := taxRec.TrIncome.Sub(WsTax)
	WsNet = storePIC9V99(wsNetRaw.Truncate(2), 7)

	WsTotalTax = WsTotalTax.Add(WsTax)
	WsTotalTax = storePIC9V99(WsTotalTax.Truncate(2), 9)

	WsCount = WsCount + 1
	// ADD 1 TO WS-COUNT with overflow? PIC 9(3) => mod 1000
	if WsCount >= 1000 {
		WsCount = WsCount % 1000
	}

	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)

	performReadPara()
}

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as EOF
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	taxFile = f
	taxFileScanner = bufio.NewScanner(f)
	// Increase buffer if needed
	buf := make([]byte, 0, 64*1024)
	taxFileScanner.Buffer(buf, 10*1024*1024)
}

func closeTaxFile() {
	if taxFile != nil {
		taxFile.Close()
	}
}

// keep old names for PERFORM mapping
func READPARA() { performReadPara() }
func PROCESSPARA() { performProcessPara() }

func init() {
	// Ensure package-level WsEofFlag consistent
	WsEofFlag = "N"
	inputDone = false
	_ = taxRec
	_ = WsEofFlag
	_ = WsTax
	_ = WsNet
	_ = WsTotalTax
	_ = WsCount
	_ = WsIncEd
	_ = WsTaxEd
	_ = WsNetEd
	_ = WsTotalEd
}

// Entry point
func main() {
	mainPara()
}
